CREATE TABLE audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,entity TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,actor TEXT NOT NULL,before_json TEXT,after_json TEXT,created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')));
CREATE INDEX audit_events_entity ON audit_events(entity,entity_id,id);
CREATE TABLE business_settings(id INTEGER PRIMARY KEY CHECK(id=1),age_days INTEGER NOT NULL DEFAULT 7,sync_days INTEGER NOT NULL DEFAULT 3,stock_threshold INTEGER NOT NULL DEFAULT 5);
INSERT INTO business_settings(id) VALUES(1);
CREATE TRIGGER audit_orders_insert AFTER INSERT ON orders BEGIN INSERT INTO audit_events(entity,entity_id,action,actor,before_json,after_json) VALUES('orders',NEW.id,'insert',audit_actor(),NULL,json_object('payload',NEW.payload,'status',NEW.status,'tracking',NEW.tracking,'atlas_state',NEW.atlas_state,'atlas_state_name',NEW.atlas_state_name,'created_email',NEW.created_email,'product_id',NEW.product_id,'unit_cost_cents',NEW.unit_cost_cents,'transport_actual_cents',NEW.transport_actual_cents,'transport_override_cents',NEW.transport_override_cents,'commission_rate',NEW.commission_rate)); END;
CREATE TRIGGER audit_orders_update AFTER UPDATE ON orders WHEN OLD.payload IS NOT NEW.payload OR OLD.status IS NOT NEW.status OR OLD.tracking IS NOT NEW.tracking OR OLD.atlas_state IS NOT NEW.atlas_state OR OLD.atlas_state_name IS NOT NEW.atlas_state_name OR OLD.created_email IS NOT NEW.created_email OR OLD.product_id IS NOT NEW.product_id OR OLD.unit_cost_cents IS NOT NEW.unit_cost_cents OR OLD.transport_actual_cents IS NOT NEW.transport_actual_cents OR OLD.transport_override_cents IS NOT NEW.transport_override_cents OR OLD.commission_rate IS NOT NEW.commission_rate BEGIN INSERT INTO audit_events(entity,entity_id,action,actor,before_json,after_json) VALUES('orders',NEW.id,'update',audit_actor(),json_object('payload',OLD.payload,'status',OLD.status,'tracking',OLD.tracking,'atlas_state',OLD.atlas_state,'atlas_state_name',OLD.atlas_state_name,'created_email',OLD.created_email,'product_id',OLD.product_id,'unit_cost_cents',OLD.unit_cost_cents,'transport_actual_cents',OLD.transport_actual_cents,'transport_override_cents',OLD.transport_override_cents,'commission_rate',OLD.commission_rate),json_object('payload',NEW.payload,'status',NEW.status,'tracking',NEW.tracking,'atlas_state',NEW.atlas_state,'atlas_state_name',NEW.atlas_state_name,'created_email',NEW.created_email,'product_id',NEW.product_id,'unit_cost_cents',NEW.unit_cost_cents,'transport_actual_cents',NEW.transport_actual_cents,'transport_override_cents',NEW.transport_override_cents,'commission_rate',NEW.commission_rate)); END;
CREATE TRIGGER audit_orders_delete AFTER DELETE ON orders BEGIN INSERT INTO audit_events(entity,entity_id,action,actor,before_json,after_json) VALUES('orders',OLD.id,'delete',audit_actor(),json_object('payload',OLD.payload,'status',OLD.status,'tracking',OLD.tracking,'atlas_state',OLD.atlas_state,'atlas_state_name',OLD.atlas_state_name,'created_email',OLD.created_email,'product_id',OLD.product_id,'unit_cost_cents',OLD.unit_cost_cents,'transport_actual_cents',OLD.transport_actual_cents,'transport_override_cents',OLD.transport_override_cents,'commission_rate',OLD.commission_rate),NULL); END;
CREATE TRIGGER audit_products_insert AFTER INSERT ON products BEGIN INSERT INTO audit_events(entity,entity_id,action,actor,before_json,after_json) VALUES('products',NEW.id,'insert',audit_actor(),NULL,json_object('name',NEW.name,'sku',NEW.sku,'stock',NEW.stock,'cost_cents',NEW.cost_cents,'sale_cents',NEW.sale_cents,'active',NEW.active)); END;
